p='src/styles.css';s=r(p);s+='''\n/* VYRON YT PEISOV 2.0 persistent publish + recovery */\n.recoveryPublishPanel{border-color:rgba(255,191,82,.28)}.recoveryUploadRows{display:grid;gap:10px}.recoveryUploadRows>div{display:grid;grid-template-columns:minmax(190px,1fr) minmax(160px,2fr) auto auto;gap:10px;align-items:center;padding:10px;border:1px solid rgba(255,255,255,.08);border-radius:14px}.recoveryUploadRows span{display:flex;flex-direction:column;gap:3px}.recoveryUploadRows small{opacity:.62}.publishStepGrid{display:grid;grid-template-columns:1.2fr .9fr .9fr;gap:12px}.publishStep{min-width:0}.publishVideoRows{display:grid;gap:6px;max-height:430px;overflow:auto}.publishVideoRows label{display:flex;align-items:center;gap:10px;padding:9px;border:1px solid rgba(255,255,255,.07);border-radius:12px}.publishVideoRows label.selected{border-color:rgba(82,214,255,.3);background:rgba(54,174,224,.06)}.publishVideoRows label span{display:flex;flex:1;min-width:0;flex-direction:column}.publishVideoRows label small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.62}.publishToolbar,.publishActions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.publishCheck{display:flex;justify-content:space-between;gap:8px;margin:12px 0;padding:10px;border:1px solid rgba(255,255,255,.07);border-radius:12px}.publishCheck.good{border-color:rgba(90,220,145,.25)}.publishCheck.warn{border-color:rgba(255,191,82,.28)}.quotaPreflightGrid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.quotaPreflightGrid>span{display:flex;flex-direction:column;padding:10px;border:1px solid rgba(255,255,255,.07);border-radius:12px}.quotaPreflightGrid small{opacity:.58}.quotaPreflightCard.blocked{border-color:rgba(255,95,117,.25)}.quotaPreflightCard.ready{border-color:rgba(90,220,145,.22)}.checkLine{display:flex;align-items:center;gap:8px;margin:10px 0}@media(max-width:1180px){.publishStepGrid{grid-template-columns:1fr}.quotaPreflightGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.recoveryUploadRows>div{grid-template-columns:1fr}}\n''';w(p,s)

